import type { ScriptLine } from "@/lib/ai/generateScript";
import type { AudioManifest, AudioSegment } from "@/lib/tts/types";

/**
 * A sample episode for trying the player without any API keys.
 * Audio files in /public/demo are silent placeholders whose lengths match
 * these lines (generated by scripts/generate-demo-audio.mts).
 */
export const DEMO_TITLE = "Database Normalisation, Explained";

export const DEMO_LINES: ScriptLine[] = [
  { speaker: "Alex", type: "dialogue", text: "Welcome back! By the end of this one, you'll know exactly why databases get split into so many tables, and how to spot when a design needs fixing." },
  { speaker: "Sam", type: "dialogue", text: "Okay, good, because honestly… normalisation has always sounded scarier than it probably is." },
  { speaker: "Alex", type: "dialogue", text: "It really is less scary than it sounds. Picture a group chat where everyone keeps re-typing the same address. One person moves, and now half the messages are wrong. Normalisation is just making sure each fact lives in one place." },
  { speaker: "Sam", type: "dialogue", text: "So it's about not repeating yourself?" },
  { speaker: "Alex", type: "dialogue", text: "Exactly. First normal form says every column holds a single value. No lists crammed into one cell, like three phone numbers separated by commas." },
  { speaker: "Sam", type: "dialogue", text: "Hmm… so if a student has three phone numbers, where do they go?" },
  { speaker: "Alex", type: "dialogue", text: "Into their own table: one row per phone number, each pointing back to the student. Same facts, but now every cell holds one value." },
  { speaker: "Alex", type: "quiz_checkpoint", text: "Okay, quick checkpoint! Pause and think for a second. What rule does first normal form add to a table?" },
  { speaker: "Sam", type: "dialogue", text: "Every column holds just one value… no lists in a cell?" },
  { speaker: "Alex", type: "dialogue", text: "Spot on. One value per cell. Next up, second normal form, which is all about partial dependencies. Let's dig in." },
];

/** Placeholder audio frames are 36 ms long, so durations are rounded to that. */
export const DEMO_FRAME_SEC = 1152 / 32000;

/** Rough spoken length: about 2.6 words per second. */
export function demoDurationSec(text: string): number {
  const words = text.split(/\s+/).length;
  const frames = Math.round(words / 2.6 / DEMO_FRAME_SEC);
  return frames * DEMO_FRAME_SEC;
}

export function demoFileName(index: number): string {
  return `${String(index).padStart(4, "0")}.mp3`;
}

export function buildDemoManifest(): AudioManifest {
  let cursor = 0;
  const segments: AudioSegment[] = DEMO_LINES.map((line, index) => {
    const durationSec = demoDurationSec(line.text);
    const next = DEMO_LINES[index + 1];
    const pauseAfterSec = !next ? 0 : line.type === "quiz_checkpoint" ? 3 : next.speaker !== line.speaker ? 0.3 : 0;
    const segment: AudioSegment = {
      index,
      lineIndex: index,
      speaker: line.speaker,
      type: line.type,
      text: line.text,
      url: `/demo/${demoFileName(index)}`,
      storagePath: `demo/${demoFileName(index)}`,
      startSec: round(cursor),
      endSec: round(cursor + durationSec),
      durationSec: round(durationSec),
      pauseAfterSec,
    };
    cursor += durationSec + pauseAfterSec;
    return segment;
  });

  return {
    version: 1,
    scriptId: "demo",
    provider: "demo",
    createdAt: "2026-11-07T00:00:00.000Z",
    totalDurationSec: round(cursor),
    manifestUrl: "",
    segments,
  };
}

function round(n: number): number {
  return Math.round(n * 1000) / 1000;
}
